function binary_search(arr, value) {
    let first = 0;
    let last = arr.length - 1;
    while (first <= last) {
        let mid = Math.floor((first + last) / 2);
        if (arr[mid] === value)
            return mid;
        else if (arr[mid] < value)
            first = mid + 1;
        else
            last = mid - 1;
    }
    return -1;
}

